-- E-Mail-Vorlagen (Ole, 14.11.2026): Anrede je Ansprache ({anrede}), Terminlink, keine Gedankenstriche.
-- Nur unveränderte Standardvorlagen werden umgestellt (alle Kunden stehen auf „Sie“); eigene Texte bleiben.
UPDATE "MailTemplate" SET "body" = E'{anrede},\n\nich habe gerade versucht, Sie telefonisch zu erreichen, leider ohne Erfolg. Sie hatten sich für {produkt} interessiert. Wann passt es Ihnen für ein kurzes Telefonat? Hier können Sie sich auch direkt einen Termin aussuchen: {terminlink}\n\n{signatur}', "updatedAt" = now() WHERE "body" = E'Hallo {vorname},\n\nich habe gerade versucht, Sie telefonisch zu erreichen – leider ohne Erfolg. Sie hatten sich für {produkt} interessiert. Wann passt es Ihnen für ein kurzes Telefonat?\n\n{signatur}';
UPDATE "MailTemplate" SET "body" = E'{anrede},\n\nwie besprochen erhalten Sie im Anhang Ihr Angebot. Wenn Sie Fragen haben, melden Sie sich gern jederzeit.\n\n{signatur}', "updatedAt" = now() WHERE "body" = E'Hallo {vorname},\n\nwie besprochen erhalten Sie im Anhang Ihr Angebot. Wenn Sie Fragen haben, melden Sie sich gern jederzeit.\n\n{signatur}';
